import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四十五卦 萃 泽地萃 兑上坤下","description":"周易 - 第四十五卦 萃 泽地萃 兑上坤下","frontmatter":{"title":"第四十五卦 萃 泽地萃 兑上坤下","description":"周易 - 第四十五卦 萃 泽地萃 兑上坤下"},"headers":[],"relativePath":"zh/classics/zhouyi/046.md","filePath":"zh/classics/zhouyi/046.md"}'),l={name:"zh/classics/zhouyi/046.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="萃" tabindex="-1">萃 <a class="header-anchor" href="#萃" aria-label="Permalink to “萃”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>萃，聚也；顺以说，刚中而应，故聚也。王假有庙，致孝享也。利见大人亨，聚以正也。用大牲吉，利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽上於地，萃；君子以除戎器，戒不虞。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>有孚不终，乃乱乃萃，若号一握 为笑，勿恤，往无咎。象曰：乃乱乃萃，其志乱也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>引吉，无咎，孚乃利用禴。象曰：引吉无咎，中未变也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>萃如，嗟如，无攸利，往无咎，小吝。象曰：往无咎，上巽也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>大吉，无咎。象曰：大吉无咎，位不当也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>萃有位，无咎。匪孚，元永贞，悔亡。象曰：萃有位，志未光也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>赍咨涕洟，无咎。象曰：赍咨涕洟，未安上也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
